function groupRelationships(values:ReturnType<typeof relationshipViews>){return values.reduce<Record<string,ReturnType<typeof relationshipViews>>>((groups,value)=>{const group=value.record.group||'General';(groups[group]??=[]).push(value);return groups;},{});}

