  if(!editing)return <section className="reading-field"><h3>{label}</h3><button className="reading-value" aria-label={`Edit ${label}`} disabled={disabled} onClick={()=>setEditing(true)}>{display||<span className="muted">-</span>}</button></section>;
  const common={autoFocus:true,'aria-label':label,value:draft,onChange:(event:React.ChangeEvent<HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement>)=>setDraft(event.target.value)};
